	mistball: { shortDesc: "50% de bajar el At. Esp. del objetivo en 1.", desc: "Tiene 50% de probabilidad de bajar el Ataque Especial del objetivo en 1 nivel." },
	mistyexplosion: { shortDesc: "Usuario se debilita. En Misty Terrain: 1.5x poder.", desc: "Si el terreno es Misty Terrain y el usuario está en tierra, el poder se multiplica por 1.5. El usuario se debilita tras usarlo, aunque falle por falta de objetivo. No se ejecuta si hay algún Pokémon con Damp en el campo." },
	mistyterrain: { shortDesc: "5 turnos: sin estado, -poder Dragon vs en tierra.", desc: "Durante 5 turnos, el terreno se vuelve Misty Terrain. El poder de ataques Dragon contra Pokémon en tierra se multiplica por 0.5, y los Pokémon en tierra no pueden sufrir estado no volátil ni confusión. Falla si el terreno ya es Misty Terrain." },
