	twinkletackle: { shortDesc: "La potencia equivale al Poder Z del movimiento base.", desc: "La potencia equivale al Poder Z del movimiento base." },
	twister: { shortDesc: "20% de hacer retroceder a los rivales.", desc: "Tiene un 20% de hacer retroceder al objetivo. La potencia se duplica si el objetivo está usando Bounce, Fly o Sky Drop, o está bajo el efecto de Sky Drop." },
	upperhand: { shortDesc: "100% de retroceso. Falla si el objetivo no usa prioridad.", desc: "Tiene un 100% de hacer retroceder al objetivo. Falla si el objetivo no eligió un movimiento de prioridad este turno, o si el objetivo se mueve antes que el usuario." },
	uproar: { shortDesc: "Dura 3 turnos. Los Pokémon activos no pueden dormir.", desc: "El usuario queda bloqueado en este movimiento tres turnos. Cada turno apunta a un oponente al azar. En el primero de los tres turnos, todos los Pokémon activos dormidos despiertan. Durante los tres turnos, ningún Pokémon activo puede dormirse por ningún medio, y los Pokémon que entran durante el efecto no despiertan. Si el usuario no puede moverse o el ataque no tiene éxito contra el objetivo en uno de los turnos, el efecto termina." },
	uturn: { shortDesc: "El usuario se retira tras dañar al objetivo.", desc: "Si este movimiento tiene éxito y el usuario no se ha debilitado, se retira aunque esté atrapado y es reemplazado de inmediato por un miembro elegido. El usuario no se retira si no hay miembros sin debilitar, o si el objetivo se retiró usando Eject Button o por las habilidades Emergency Exit o Wimp Out." },
	vacuumwave: { shortDesc: "Suele ir primero.", desc: "Sin efecto adicional." },
	vcreate: { shortDesc: "Baja Defensa, Def. Esp. y Velocidad del usuario en 1.", desc: "Baja la Velocidad, Defensa y Defensa Especial del usuario en 1 nivel." },
	veeveevolley: { shortDesc: "Felicidad máxima: 102 de potencia. No falla.", desc: "La potencia es igual al mayor valor entre (Felicidad del usuario * 2/5), redondeado hacia abajo, o 1." },
	venomdrench: { shortDesc: "Baja At/At.Esp/Velocidad de rivales envenenados en 1.", desc: "Baja el Ataque, Ataque Especial y Velocidad del objetivo en 1 nivel si está envenenado. Falla si el objetivo no está envenenado." },
	venoshock: { shortDesc: "La potencia se duplica si el objetivo está envenenado.", desc: "La potencia se duplica si el objetivo está envenenado." },
	victorydance: { shortDesc: "Sube Ataque, Defensa y Velocidad del usuario en 1.", desc: "Sube el Ataque, Defensa y Velocidad del usuario en 1 nivel." },
